#!/usr/bin/env bash
# shellcheck disable=SC2048,SC2086
#
# SPDX-FileCopyrightText: 2021-2026 MDP43140
# SPDX-License-Identifier: GPL-3.0-or-later
#
# This script extracts DNS queries generated by TCPDump program"
# Usage: $0 [files]"
#        tcpdump | $0"
#
sed -En 's/.*A\? (.+)\. .*/\1/p;/\.arpa/d;/\.local/d' $* \
 | sort -ui;
